contract InvMutTest is Test {
    AirDropContract c;
    function setUp() public { c = new AirDropContract(); }

    function testFuzz_property(address caller, uint8 n) public {
        uint256 len = uint256(n) % 11;

        GoodRecipient r = new GoodRecipient();

        address[] memory tos = new address[](len);
        uint[] memory vs = new uint[](len);
        for (uint i = 0; i < len; i++) {
            tos[i] = address(r);
            vs[i] = 1 + i;
        }

        bool ok;
        vm.prank(caller);
        try c.transfer(address(r), tos, vs) returns (bool ret) {
            ok = ret;
        } catch {
            ok = false;
        }

        if (len > 0) {
            assertTrue(ok);
        } else {
            assertTrue(!ok);
        }
    }
}

